<script setup>
import { ref } from 'vue'
import { questionnaire as form } from '../questionnaire.js'
const adding=ref(false), medication=ref(''), frequency=ref('Once daily')
const options=[['🏋️','Gentle exercise'],['🥗','Diet changes'],['💬','Therapy or CBT'],['💊','Magnesium'],['🌿','Acupuncture'],['🌙','Sleep routine'],['🧘','Yoga']]
function toggle(name){const index=form.solutions.indexOf(name);if(index<0)form.solutions.push(name);else form.solutions.splice(index,1)}
function addMedication(){if(!medication.value.trim())return;form.medications.push({name:medication.value.trim(),frequency:frequency.value.trim()||'Not specified',source:'Added by you'});medication.value='';adding.value=false}
</script>
<template>
<div class="design-screen stack questions-page"><header class="page-header"><a class="icon-btn" href="#patterns" aria-label="Back to Patterns">‹</a><h1>3 Pre Menstrual<br>Summary Questions</h1></header>
<section class="card"><h2><span class="question-number">1</span>What other solutions have you explored?</h2><div class="chip-row"><button v-for="[emoji,name] in options" :key="name" class="chip" :aria-pressed="form.solutions.includes(name)" @click="toggle(name)"><span>{{emoji}}</span> {{name}}</button></div></section>
<section class="card"><h2><span class="question-number">2</span>What medication are you taking?</h2><div v-for="(med,i) in form.medications" :key="i" class="medication"><div><strong>{{med.name}}</strong><span class="muted">{{med.frequency}}</span><small>{{med.source}}</small></div><button class="remove" :aria-label="'Remove '+med.name" @click="form.medications.splice(i,1)">×</button></div><p v-if="!form.medications.length" class="muted">No medications added.</p><button class="secondary full" @click="adding=!adding" :aria-expanded="adding">＋ Add medication or solution</button><form v-if="adding" @submit.prevent="addMedication"><label class="field">Medication or solution<input v-model="medication" required maxlength="100" placeholder="Name and dose"></label><label class="field">Frequency<input v-model="frequency" maxlength="100" placeholder="e.g. Once daily"></label><button class="primary full">Add medication</button></form></section>
<section class="card"><h2><span class="question-number">3</span>To what extent does this affect your daily life?</h2><div class="impact-face" aria-hidden="true">{{['😊','🙂','😐','😟','😣'][form.impact-1]}}</div><label class="field" for="impact">Impact on daily life: {{form.impact}} of 5<input id="impact" v-model.number="form.impact" type="range" min="1" max="5" step="1"></label><div class="scale-labels"><span>A little</span><span>A lot</span></div><label class="field">Anything you would like your clinician to know?<textarea v-model="form.notes" rows="4" placeholder="How does it affect work, sleep, relationships or your day-to-day life?" maxlength="2000"></textarea></label></section>
<div class="create-summary"><a href="#summary" class="primary full">Create summary for healthcare professional →</a><p class="muted">Nothing is shared until you choose to send it.</p></div></div>
</template>
<style scoped>
.questions-page{background:#eedee9!important}.page-header{justify-content:flex-start;padding-bottom:10px}h1{font-family:Georgia,serif;font-style:italic;font-size:23px;font-weight:500;color:#6d5383;line-height:1.3}.card{background:#fbf8f8}h2{font-size:14px;line-height:1.8;color:#556151}.question-number{font-size:12px}.chip span{font-size:19px;margin-right:5px}.medication{border-top:1px solid #e8e2e7;padding:13px 0;display:flex;align-items:center;justify-content:space-between}.medication strong,.medication small,.medication .muted{display:block}.medication strong{font-size:13px}.medication small{font-size:10px;color:#81778c;margin-top:4px}.remove{background:transparent;border:0;color:#8a657d;font-size:24px;width:44px;height:44px}.impact-face{text-align:center;font-size:65px;margin:24px 0}.scale-labels{display:flex;justify-content:space-between;font-size:11px;color:#70627c}input[type=range]{accent-color:#8c60a8;padding:0;border:0}.create-summary{margin:4px 14px;text-align:center}.create-summary a{display:block}.create-summary p{font-size:10px}
</style>
